-- Disposable PostgreSQL 18 contract test for a least-privilege logical backup role.
-- Run only against the ephemeral CI service. No external database or repository secrets.
BEGIN;

CREATE ROLE backup_contract_test LOGIN PASSWORD 'backup-contract-test-only'
  NOSUPERUSER NOCREATEDB NOCREATEROLE NOREPLICATION NOBYPASSRLS NOINHERIT;
CREATE SCHEMA backup_contract_fixture;
CREATE TABLE backup_contract_fixture.sample (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  payload text NOT NULL
);
INSERT INTO backup_contract_fixture.sample (payload) VALUES ('synthetic-backup-fixture');

GRANT CONNECT ON DATABASE microapp_test TO backup_contract_test;
GRANT USAGE ON SCHEMA backup_contract_fixture TO backup_contract_test;
GRANT SELECT ON ALL TABLES IN SCHEMA backup_contract_fixture TO backup_contract_test;
GRANT SELECT ON ALL SEQUENCES IN SCHEMA backup_contract_fixture TO backup_contract_test;

DO $assert_backup_contract$
DECLARE
  role_row record;
  role_oid oid;
  sequence_name text;
BEGIN
  SELECT * INTO role_row FROM pg_catalog.pg_roles WHERE rolname = 'backup_contract_test';
  IF NOT FOUND OR NOT role_row.rolcanlogin OR role_row.rolsuper OR role_row.rolcreaterole
     OR role_row.rolcreatedb OR role_row.rolreplication OR role_row.rolbypassrls
     OR role_row.rolinherit THEN
    RAISE EXCEPTION 'BACKUP_CONTRACT_ROLE_ATTRIBUTES_FAILED';
  END IF;

  role_oid := role_row.oid;
  IF EXISTS (
    SELECT 1 FROM pg_catalog.pg_auth_members
    WHERE member = role_oid OR roleid = role_oid
  ) THEN
    RAISE EXCEPTION 'BACKUP_CONTRACT_ROLE_MEMBERSHIP_FAILED';
  END IF;

  IF NOT pg_catalog.has_database_privilege('backup_contract_test', current_database(), 'CONNECT')
     OR pg_catalog.has_database_privilege('backup_contract_test', current_database(), 'CREATE')
     OR NOT pg_catalog.has_schema_privilege('backup_contract_test', 'backup_contract_fixture', 'USAGE')
     OR pg_catalog.has_schema_privilege('backup_contract_test', 'backup_contract_fixture', 'CREATE')
     OR NOT pg_catalog.has_table_privilege('backup_contract_test', 'backup_contract_fixture.sample', 'SELECT')
     OR pg_catalog.has_table_privilege('backup_contract_test', 'backup_contract_fixture.sample', 'INSERT')
     OR pg_catalog.has_table_privilege('backup_contract_test', 'backup_contract_fixture.sample', 'UPDATE')
     OR pg_catalog.has_table_privilege('backup_contract_test', 'backup_contract_fixture.sample', 'DELETE')
     OR pg_catalog.has_table_privilege('backup_contract_test', 'backup_contract_fixture.sample', 'TRUNCATE') THEN
    RAISE EXCEPTION 'BACKUP_CONTRACT_TABLE_OR_SCHEMA_PRIVILEGES_FAILED';
  END IF;

  sequence_name := pg_catalog.pg_get_serial_sequence('backup_contract_fixture.sample', 'id');
  IF sequence_name IS NULL
     OR NOT pg_catalog.has_sequence_privilege('backup_contract_test', sequence_name, 'SELECT')
     OR pg_catalog.has_sequence_privilege('backup_contract_test', sequence_name, 'USAGE')
     OR pg_catalog.has_sequence_privilege('backup_contract_test', sequence_name, 'UPDATE') THEN
    RAISE EXCEPTION 'BACKUP_CONTRACT_SEQUENCE_PRIVILEGES_FAILED';
  END IF;
END;
$assert_backup_contract$;

COMMIT;
